    Bug 1952094 - For localfolder copy, use msgKey from final header in nsIMsgCopyServiceListener.setMessageKey() invocations. r=darktrojan

    The local folder copystate stores the nsMsgKey of the new msgHdr at time of
    creation, and later sends that key out to the listener. This is fine for the
    legacy (mork) code, where the key is assigned before the msgHdr is added to
    the database and doesn't change.
    But it's no good for panorama, which assigns the key later, when the row is
    created in the database. This patch ensures the final key value - for either
    database system - is sent out via nsIMsgCopyServiceListener.setMessageKey().

    Differential Revision: https://phabricator.services.mozilla.com/D251247

diff --git a/mailnews/local/src/nsLocalMailFolder.cpp b/mailnews/local/src/nsLocalMailFolder.cpp
index 395648224a0..0368483049e 100644
--- a/mailnews/local/src/nsLocalMailFolder.cpp
+++ b/mailnews/local/src/nsLocalMailFolder.cpp
@@ -2331,8 +2331,13 @@ nsMsgLocalMailFolder::EndCopy(bool aCopySucceeded) {
                                            // we can't undo w/o the msg db

     mCopyState->m_parseMsgState->Clear();
-    if (mCopyState->m_listener)  // CopyFileMessage() only
-      mCopyState->m_listener->SetMessageKey(mCopyState->m_curDstKey);
+    if (mCopyState->m_listener && newHdr) {  // CopyFileMessage() only
+      // Tell the nsIMsgCopyServiceListener about the new key.
+      nsMsgKey newKey;
+      newHdr->GetMessageKey(&newKey);
+      MOZ_ASSERT(newKey != nsMsgKey_None);
+      mCopyState->m_listener->SetMessageKey(newKey);
+    }
   }

   if (!multipleCopiesFinished && !mCopyState->m_copyingMultipleMessages) {
@@ -2585,8 +2590,13 @@ NS_IMETHODIMP nsMsgLocalMailFolder::EndMessage(nsMsgKey key) {
     }
     mCopyState->m_parseMsgState->Clear();

-    if (mCopyState->m_listener)  // CopyFileMessage() only
-      mCopyState->m_listener->SetMessageKey(mCopyState->m_curDstKey);
+    if (mCopyState->m_listener && newHdr) {  // CopyFileMessage() only
+      // Tell the nsIMsgCopyServiceListener about the new key.
+      nsMsgKey newKey;
+      newHdr->GetMessageKey(&newKey);
+      MOZ_ASSERT(newKey != nsMsgKey_None);
+      mCopyState->m_listener->SetMessageKey(newKey);
+    }
   }

   return NS_OK;
